#!/usr/bin/env python3
from pathlib import Path
import base64
R=Path(__file__).resolve().parents[1]
def uri(n):
 return 'data:image/webp;base64,'+base64.b64encode((R/'assets'/n).read_bytes()).decode()
scenes=[uri('skyline.webp'),uri('chamber.webp'),uri('verdict.webp')]
html=r'''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#070d18"><title>ADVERSE JUDGE — Three Scene Film</title>
<style>
:root{font-family:Arial,Helvetica,sans-serif;color:#f6f2e7;background:#070d18}*{box-sizing:border-box}body{margin:0}button{font:inherit;cursor:pointer}button:focus-visible{outline:2px solid #ffe3ac;outline-offset:4px}.film{position:relative;isolation:isolate;min-height:100dvh;display:flex;flex-direction:column;overflow:hidden;background:#080e19}.plate{position:absolute;inset:0;background-size:cover;background-position:center;z-index:-3;animation:dolly 28s ease-in-out alternate infinite}.shade{position:absolute;inset:0;z-index:-2;background:linear-gradient(90deg,rgba(4,8,15,.98),rgba(5,12,24,.86) 35%,rgba(7,11,18,.26) 100%),linear-gradient(0deg,rgba(3,7,12,.8),transparent 45%)}.grain{pointer-events:none;position:absolute;inset:0;z-index:-1;background:radial-gradient(ellipse at 70% 40%,transparent 30%,rgba(2,5,9,.66) 100%)}.head,.foot{padding:32px clamp(22px,5vw,85px);display:flex;justify-content:space-between;align-items:center;gap:16px}.logo{font-size:17px;letter-spacing:.2em;text-transform:uppercase}.logo b{color:#f2c88d}.kicker{font-size:10px;letter-spacing:.28em;color:#dbbc86}.head button{background:#111c2c;color:#f2e4cb;border:1px solid #76684f;border-radius:40px;padding:9px 16px;font-size:11px}.body{flex:1;display:flex;flex-direction:column;justify-content:center;width:min(740px,90vw);padding:45px 0;margin-left:clamp(22px,13vw,210px)}h1{font:normal clamp(51px,7vw,104px)/.98 Georgia,'Times New Roman',serif;letter-spacing:-.06em;margin:20px 0 30px;max-width:800px}p{color:#d0d6d7;line-height:1.75;font-size:clamp(14px,1.4vw,18px);max-width:560px}.actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:28px;max-width:670px}.action{background:rgba(10,21,34,.84);color:#f5e6cc;border:1px solid rgba(231,208,168,.35);padding:18px;text-align:left;min-height:90px;display:flex;flex-direction:column;justify-content:center;border-radius:6px;backdrop-filter:blur(8px);transition:border-color .25s,background .25s}.action strong{font-size:14px}.action small{margin-top:8px;color:#b1babe}.action:hover{border-color:#e8c68f;background:rgba(52,42,31,.88)}.action:focus-visible{outline-offset:4px}.action.primary{border-color:#dbb67d;background:rgba(83,58,30,.34)}.foot{border-top:1px solid #8e765644;color:#d4d4d6;font-size:10px;letter-spacing:.12em}.bar{width:160px;background:#54617555;height:3px}.bar span{display:block;height:100%;background:#ddbf8c;transition:width .5s}.foot button{border:0;background:transparent;color:#f1e0c5;padding:12px}.outcome{border-left:2px solid #dcb880;padding:16px 22px;background:#07111fcc;max-width:590px;line-height:1.7;color:#f4e2bc}#notice{font-size:12px;color:#dbba85}@keyframes dolly{from{transform:scale(1.04)}to{transform:scale(1.15) translateX(-2%)}}@media(max-width:650px){.head,.foot{padding:20px}.head{align-items:flex-start}.logo{font-size:13px}.body{width:calc(100% - 40px);margin:0 20px;padding:35px 0;justify-content:flex-start}.film{min-height:100dvh}h1{font-size:clamp(45px,12vw,70px)}.actions{grid-template-columns:1fr;margin-top:12px}.action{min-height:68px;padding:14px}p{font-size:14px}.shade{background:linear-gradient(90deg,#050b16ee,#071020ba),linear-gradient(0deg,#050b16cc,transparent)}.foot .bar{width:80px}}@media(prefers-reduced-motion:reduce){.plate{animation:none!important}*{transition:none!important}}.lite .plate{animation:none!important}
</style></head><body>
<div class="film" id="film"><div class="plate" id="plate"></div><div class="shade"></div><div class="grain"></div><header class="head"><div class="logo">ADVERSE <b>JUDGE</b></div><div><button id="sound" aria-pressed="false">♪ ЗВУК</button> <button id="quality">◐ LITE</button></div></header><main class="body" id="story" aria-live="polite"></main><footer class="foot"><span id="step">01 / 03</span><div class="bar"><span id="bar" style="width:33%"></span></div><span id="notice">ПРОГРЕСС СОХРАНЯЕТСЯ ЛОКАЛЬНО</span><button id="restart">↺ ЗАНОВО</button></footer></div>
<script>
const PLATES=__PLATES__;
const STEPS=[{id:'intro',label:'НЕЗАРЕГИСТРИРОВАННОЕ ДЕЛО 001',headline:'Слова имеют последствия.',desc:'За пределами города открыт Трибунал. Сегодня перед ним предстоит одно рекламное обещание.'},{id:'choice',label:'ЗАЛ ВЫБОРА',headline:'Что важнее — громкость или правда?',desc:'Выберите, как изменить сообщение. Этот выбор повлияет на итог.'},{id:'ending',label:'РЕШЕНИЕ ЗРИТЕЛЯ',headline:'Главный свидетель — вы.',desc:'Простая мысль меняет смысл рекламы. Вы выбрали, чего человек должен ожидать от бренда.'}];
const storeKey='adverse.cinema.three-scene.v1';let data={step:0,strategy:null},lite=false,sound=false,audio=null;
try{data={...data,...JSON.parse(localStorage.getItem(storeKey)||'null')}}catch(e){};
if(data.step>2||data.step<0)data.step=0;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\"':'&quot;'}[c]));
function save(){try{localStorage.setItem(storeKey,JSON.stringify(data))}catch(e){}}
function tone(){if(!sound)return;try{const a=audio||(audio=new (window.AudioContext||window.webkitAudioContext)());a.resume();const o=a.createOscillator(),g=a.createGain();o.type='sine';o.frequency.value=220+data.step*85;g.gain.setValueAtTime(.0001,a.currentTime);g.gain.exponentialRampToValueAtTime(.055,a.currentTime+.06);g.gain.exponentialRampToValueAtTime(.0001,a.currentTime+.45);o.connect(g);g.connect(a.destination);o.start();o.stop(a.currentTime+.47)}catch(e){}}
function setStep(n,strategy){data.step=n;if(strategy)data.strategy=strategy;save();render();tone()}
function render(){const s=STEPS[data.step];document.getElementById('plate').style.backgroundImage=`url("${PLATES[data.step]}")`;document.getElementById('step').textContent='0'+(data.step+1)+' / 03';document.getElementById('bar').style.width=(data.step+1)*100/3+'%';const root=document.getElementById('story');root.innerHTML='';const label=document.createElement('div');label.className='kicker';label.textContent=s.label;root.appendChild(label);const h=document.createElement('h1');h.textContent=s.headline;root.appendChild(h);const p=document.createElement('p');p.textContent=s.desc;root.appendChild(p);if(data.step===2){const out=document.createElement('div');out.className='outcome';out.textContent=data.strategy==='proof'?'Решение: сначала доказательства. Ваше новое правило — любое измеримое утверждение требует проверяемого источника.':'Решение: сначала ясность. Ваше новое правило — объясните реальную пользу и важные ограничения без абсолютных гарантий.';root.appendChild(out);}const actions=document.createElement('div');actions.className='actions';const buttons=data.step===0?[['Войти в Трибунал','Начать расследование',()=>setStep(1)]]:data.step===1?[['Уточнить обещание','Для кого и при каких условиях?',()=>setStep(2,'clarity')],['Требовать основания','Какие данные подтверждают результат?',()=>setStep(2,'proof')]]:[['Посмотреть другой исход','Вернуться к выбору стратегии',()=>setStep(1)],['Повторить фильм','Пройти три сцены заново',()=>{data={step:0,strategy:null};save();render()}]];buttons.forEach(([name,detail,handler],i)=>{const b=document.createElement('button');b.className='action'+(!i?' primary':'');b.innerHTML='<strong>'+esc(name)+'</strong><small>'+esc(detail)+'</small>';b.onclick=handler;actions.appendChild(b)});root.appendChild(actions);}
document.getElementById('sound').onclick=e=>{sound=!sound;e.currentTarget.setAttribute('aria-pressed',String(sound));e.currentTarget.textContent=sound?'♫ ЗВУК ВКЛ':'♪ ЗВУК';if(sound)tone()};
document.getElementById('quality').onclick=e=>{lite=!lite;document.getElementById('film').classList.toggle('lite',lite);e.currentTarget.textContent=lite?'◐ LITE':'◐ CINEMATIC'};
document.getElementById('restart').onclick=()=>{data={step:0,strategy:null};save();render()};
render();
</script></body></html>'''
html=html.replace('__PLATES__','['+','.join('"'+x+'"' for x in scenes)+']')
out=R/'dist/ADVERSE-JUDGE-THREE-SCENE-PROTOTYPE.html';out.write_text(html,'utf-8')
print('Built 3-scene prototype',out.stat().st_size)
